const items = $input.all();
const flagged = [];
const toProb = function(odds) { return odds > 0 ? 100 / (odds + 100) : (-odds) / (-odds + 100); };

for (const item of items) {
  const game = item.json;
  const bookmakers = game.bookmakers || [];
  const hardRock = bookmakers.find(function(b) { return b.key === "hardrockbet"; });
  const pinnacle = bookmakers.find(function(b) { return b.key === "pinnacle"; });
  if (!hardRock || !pinnacle) continue;

  const hrMarket = (hardRock.markets || []).find(function(m) { return m.key === "h2h"; });
  const pinMarket = (pinnacle.markets || []).find(function(m) { return m.key === "h2h"; });
  if (!hrMarket || !pinMarket) continue;

  const pinOutcomes = pinMarket.outcomes || [];
  const pinImplied = pinOutcomes.map(function(o) { return { name: o.name, prob: toProb(o.price) }; });
  const pinTotal = pinImplied.reduce(function(sum, o) { return sum + o.prob; }, 0);
  const pinTrue = pinImplied.map(function(o) { return { name: o.name, prob: o.prob / pinTotal }; });

  const hrOutcomes = hrMarket.outcomes || [];
  for (const hrOutcome of hrOutcomes) {
    const trueEntry = pinTrue.find(function(o) { return o.name === hrOutcome.name; });
    if (!trueEntry) continue;
    const hrImplied = toProb(hrOutcome.price);
    const edge = trueEntry.prob - hrImplied;
    if (edge > 0.03) {
      flagged.push({
        matchup: (game.home_team || "") + " vs " + (game.away_team || ""),
        sport: game.sport_title || "",
        commenceTime: game.commence_time || "",
        pick: hrOutcome.name,
        hardRockOdds: hrOutcome.price,
        impliedProbPct: Math.round(hrImplied * 1000) / 10,
        trueProbPct: Math.round(trueEntry.prob * 1000) / 10,
        edgePct: Math.round(edge * 1000) / 10
      });
    }
  }
}

flagged.sort(function(a, b) { return b.edgePct - a.edgePct; });

const lines = flagged.map(function(f) {
  return f.sport + ": " + f.matchup + "\n  Pick: " + f.pick + " (" + f.hardRockOdds + ")\n  Hard Rock implies " + f.impliedProbPct + "% | sharp-market estimate " + f.trueProbPct + "% | edge +" + f.edgePct + "%";
});

const disclaimer = "\n\n---\nAutomated edge estimate based on Hard Rock vs. Pinnacle pricing. Not financial advice, no guarantee of outcome. Bet responsibly.";
const emailBody = (lines.length > 0 ? lines.join("\n\n") : "No bets cleared the edge threshold this run.") + disclaimer;

return [{ json: { flaggedCount: flagged.length, emailBody: emailBody, picks: flagged } }];
